  "Removed {n} chest records and the scan from history.": { one: "Удалена {n} запись сундука и сканирование из истории.", few: "Удалены {n} записи сундуков и сканирование из истории.", many: "Удалено {n} записей сундуков и сканирование из истории.", other: "Удалено {n} записей сундуков и сканирование из истории." },
